(() => {
  'use strict';
  const {SAMPLE,AgentRuntime}=WorkshopCore;
  const KEY='ai-agent-workshop.v1';
  const uid=()=>crypto.randomUUID();
  const identity=WorkshopIdentity;
  const makeAgent=(name,index=state?.agents?.length||0)=>({...identity.defaults(name,index),id:uid(),name,role:'Document explorer',instructions:'Summarize the document accurately. Use bullets.',format:'concise',tool:true,document:SAMPLE,version:1});
  const first=makeAgent('Moss',0);
  let state={agents:[first],selected:first.id,runs:[],messages:[],tutorial:{schema:2,active:false,step:0},settings:{advanced:false},ui:{view:'workshop',zoom:1},drafts:{agents:{},chats:{},evaluations:{}}};
  let storageOK=true;
  try {const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.agents?.length&&Array.isArray(saved.runs)&&Array.isArray(saved.messages))state=saved;}catch{storageOK=false;}
  // Keep the v1 storage key and original IDs: an upgrade must never replace existing agents.
  state.agents=state.agents.map(identity.normalize);
  state.settings={advanced:false,tutorialDisabled:false,...state.settings};
  state.ui={view:'workshop',zoom:1,...state.ui};
  state.drafts={agents:{},chats:{},evaluations:{},...state.drafts};
  if(state.tutorial?.schema!==2){state.legacyTutorial=state.tutorial;state.tutorial={schema:2,active:false,step:0};}
  if(!state.agents.some(a=>a.id===state.selected))state.selected=state.agents[0].id;
  const data=WorkshopData;data.migrate(state);
  let view=['workshop','blueprint','laboratory','learn','roster','queue','sessions','settings'].includes(state.ui.view)?state.ui.view:'workshop',selectedRun=null,modal=!!state.ui.creation,formError='',openEvents=new Set(),comparisonVisible=false;
  const runtimes=new Map(),failureNext=new Set();
  const agent=()=>state.agents.find(a=>a.id===state.selected)||state.agents[0];
  const runs=(id=agent().id)=>state.runs.filter(r=>r.agentId===id);
  const latest=(id=agent().id)=>runs(id)[0];
  const currentRun=()=>runs().find(r=>r.id===selectedRun)||latest();
  const status=(id=agent().id)=>runs(id).find(r=>['working','using-tool','paused'].includes(r.status))?.status||(data.pending(state,id).length?'queued':latest(id)?.status||'idle');
  const busy=(id=agent().id)=>Boolean(runtimes.get(id)?.active);
  const runtime=(id=agent().id)=>{if(!runtimes.has(id)){const rt=new AgentRuntime();rt.subscribe(onRuntimeEvent);runtimes.set(id,rt);}return runtimes.get(id);};
  const liveTutorial=()=>state.tutorial.active&&!state.tutorial.paused&&!state.settings.tutorialDisabled;
  const chatDraft=()=>state.drafts.chats[agent().id]||'';
  const configDraft=()=>state.drafts.agents[agent().id]||null;
  const bot=(a=agent())=>identity.bot(a);
  const style=(a=agent())=>identity.style(a);
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const time=value=>new Date(value).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});
  const icons={workshop:'<path d="M3 10 12 3l9 7v11H3z"/><path d="M9 21v-8h6v8"/>',blueprint:'<rect x="3" y="3" width="7" height="6" rx="1"/><rect x="14" y="15" width="7" height="6" rx="1"/><path d="M7 9v9h7M17 15V6h-7"/>',laboratory:'<path d="M9 3h6M10 3v7L4 20h16l-6-10V3M8 15h8"/>',learn:'<path d="M3 5c4-2 6-1 9 1 3-2 5-3 9-1v15c-4-2-6-1-9 1-3-2-5-3-9-1zM12 6v15"/>'};
  const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.workshop}</svg>`;

  function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;}}
  function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3800);}
  const steps=[
    {lesson:1,title:'Meet Practice Moss, your sandbox agent',text:'Click Practice Moss’s workstation in the shared room. Selecting a character opens only that agent’s conversation; everyone else stays in the room.',view:'workshop',action:'meet'},
    {lesson:2,title:'Create someone new',text:'Select New agent. Give your new companion a name, choose an avatar shape and rainbow color, then continue to Instructions & tools.',view:'workshop',action:'identity'},
    {lesson:3,title:'Give your new agent a job',text:'Edit its instructions and keep the Sample document tool enabled. This is a new-agent draft; Moss is unchanged. Select Review agent when ready.',view:'workshop',action:'configure'},
    {lesson:4,title:'Save your new agent to the Workshop',text:'Check the review, then select Create Agent. This adds a separate identity and workstation, with its own configuration and history.',view:'workshop',action:'create'},
    {lesson:5,title:'Assign a simulated task',text:'Select Summarize document, then Run task. Only your selected agent receives the task; all other agents stay visible.',view:'workshop',action:'assign'},
    {lesson:6,title:'Observe its activity',text:'Watch your agent’s animation and named activity stream, then select Open Laboratory to see the events. Working, using a tool, and waiting are actual simulator states.',view:'workshop',action:'observe'},
    {lesson:7,title:'Inspect the result',text:'Expand Inspect agent output. Read the summary and expand Document received to compare it with the source. These are observable records, not hidden model reasoning.',view:'laboratory',action:'inspect'},
    {lesson:8,title:'Evaluate the first result',text:'Choose accuracy and coverage scores, add a review note if useful, and select Save evaluation. Look for missing limitations or uncertainty in the short summary.',view:'laboratory',action:'score'},
    {lesson:8,title:'Improve the instructions',text:'Select Add risk review instruction, or add “Include risks and uncertainty” yourself. Then select Save Changes. The earlier run keeps its original configuration.',view:'blueprint',action:'improve'},
    {lesson:8,title:'Run the same task again',text:'The same task is ready to send. Select Run task and observe how a supported instruction change affects the simulation.',view:'workshop',action:'rerun'},
    {lesson:8,title:'Compare your experiments',text:'When the second run finishes, select Compare latest two in Laboratory. Compare the summaries and their saved instructions to see why the result changed.',view:'laboratory',action:'compare'}
  ];
  state.tutorial.progress ||= Object.fromEntries(Array.from({length:state.tutorial.step||0},(_,i)=>[i,'completed']));
  function advance(action,message){const t=state.tutorial;if(!liveTutorial()||steps[t.step]?.action!==action)return false;t.progress ||= {};t.progress[t.step]='completed';t.help=false;t.step++;t.lastSuccess=message||'Action completed. Your progress is saved.';save();toast(t.lastSuccess);return true;}
  function highlight(){return '';}
  function tutorialHelp(){
    const t=state.tutorial,step=steps[t.step];if(!step)return '';
    const baseline=state.runs.find(r=>r.id===t.baseline);
    const missing=t.step>=4&&!state.agents.some(a=>a.id===t.agentId)?'You skipped creating a practice agent. Prepare a practice agent below, then assign a task.':t.step>=6&&t.step<=9&&baseline?.status!=='completed'?'This step needs a completed practice task. Run “Summarize the sample document” in Workshop, wait for completion, then return here.':t.step===10&&runs(t.agentId).filter(r=>r.status==='completed').length<2?'Comparison needs two completed tasks for the same practice agent. Run the same task twice, changing its instructions between runs.':'The highlighted control is the next action. You can also skip this action without completing it.';
    return `<div class="tutorial-help" role="status"><strong>What to do: ${esc(step.title)}</strong><p>${step.text}</p><p><strong>Prerequisite / recovery:</strong> ${missing}</p><button data-action="guide-me">Show the control / retry</button> <button data-action="prepare-practice">Prepare practice agent</button> <button data-action="skip-step">Skip this step</button></div>`;
  }
  function tutorial(){const t=state.tutorial;if(state.settings.tutorialDisabled)return '';
    const records=t.progress||{},completed=Object.values(records).filter(x=>x==='completed').length,skipped=Object.values(records).filter(x=>x==='skipped').length;
    const progress=`<p>${completed} completed · ${skipped} skipped · ${steps.length-completed-skipped} unfinished actions</p>`;
    if(!t.active)return `<section class="panel tutorial"><div class="tutorial-icon">✧</div><div><div class="eyebrow">Learn by doing · 8 lessons</div><h3>Your first agent</h3><p>Practice safely. Every step can be skipped; your progress is saved.</p>${progress}</div><div class="tutorial-actions"><button class="primary" data-action="${t.step<steps.length&&t.starterId?'continue-tutorial':'start-tutorial'}">${t.starterId&&t.step<steps.length?'Resume tutorial':'Start guided tutorial'}</button><button data-action="restart-tutorial">Restart tutorial</button></div></section>`;
    if(t.step>=steps.length)return `<section class="panel tutorial"><div class="tutorial-icon">✓</div><div><h3>Tutorial reviewed</h3>${progress}<p>Skipped actions remain skipped. Revisit an action in Field guide whenever you like.</p></div><div class="tutorial-actions"><button data-action="tutorial-back">Back</button><button data-action="restart-tutorial">Restart tutorial</button><button data-action="skip-tutorial">Exit tutorial</button></div></section>`;
    const step=steps[t.step];return `<section class="panel tutorial tutorial-current" aria-label="Guided tutorial"><div class="tutorial-icon">${t.paused?'Ⅱ':step.lesson}</div><div><div class="eyebrow">${t.paused?'Tutorial paused':'Current objective'} · Lesson ${step.lesson} of 8 · Action ${t.step+1} of ${steps.length}</div><h3>${step.title}</h3><p>${t.paused?'Explore freely. Resume when ready.':step.text}</p>${t.lastSuccess?`<p class="lesson-success" role="status">${esc(t.lastSuccess)}</p>`:''}${progress}<div class="progress">${steps.map((_,i)=>`<i title="Action ${i+1}: ${records[i]||'unfinished'}" class="${records[i]==='completed'?'done':records[i]==='skipped'?'skipped':''}"></i>`).join('')}</div>${t.help?tutorialHelp():''}</div><div class="tutorial-actions"><button data-action="tutorial-back" ${t.step===0?'disabled':''}>Back</button>${records[t.step]?'<button data-action="tutorial-next">Next →</button>':''}<button class="primary" data-action="${t.paused?'continue-tutorial':'guide-me'}">${t.paused?'Resume tutorial':'Show required action'}</button><button data-action="tutorial-help">I’m stuck / Help me</button><button data-action="skip-step">Skip Step →</button><button data-action="pause-tutorial">Pause tutorial</button><button data-action="skip-tutorial">Exit tutorial</button><button data-action="restart-tutorial">Restart tutorial</button></div></section>`;
  }
  function preparePractice(){
    const t=state.tutorial;let a=state.agents.find(a=>a.id===t.agentId&&a.practice);
    if(!a){a=makeAgent('Practice explorer');a.practice=true;state.agents.push(a);t.agentId=a.id;}
    a.lifecycle='active';ensureSession(a);state.selected=a.id;modal=false;if(state.ui.creation?.practice)state.ui.creation=null;state.drafts.chats[a.id]='Summarize the sample document';save();go('workshop');
  }
  function resetExperiment(){
    const ids=new Set(state.agents.filter(a=>a.practice===true).map(a=>a.id));
    ids.forEach(id=>{runtimes.get(id)?.cancel();runtimes.delete(id);delete state.drafts.agents[id];delete state.drafts.chats[id];});
    state.agents=state.agents.filter(a=>!ids.has(a.id));state.runs=state.runs.filter(r=>!ids.has(r.agentId));state.messages=state.messages.filter(m=>!ids.has(m.agentId));
    state.sessions=state.sessions.filter(x=>!ids.has(x.agentId));state.memories=state.memories.filter(x=>!ids.has(x.agentId));state.handoffs=state.handoffs.filter(h=>!ids.has(h.senderId)&&!ids.has(h.recipientId));ids.forEach(id=>{delete state.versions[id];delete state.queuePaused[id];});
    if(state.ui.creation?.practice)state.ui.creation=null;modal=false;startTutorial();toast('Practice fixtures reset. Personal agents and their records were preserved.');
  }
  function room(){if(!state.agents.some(a=>a.lifecycle==='active'))return '<div class="empty-room"><h3>Your agents are resting</h3><p>Return an agent from the roster to bring its workstation back.</p><button data-view="roster">Open Agent Roster</button></div>';if(WorkshopTheme.current==='neon')return WorkshopHeadquarters.scene(state.agents.filter(a=>a.lifecycle==='active'),state.selected,status,esc,state.ui.zoom);return WorkshopTheme.room(identity.room(state.agents.filter(a=>a.lifecycle!=='resting'&&a.lifecycle!=='archived'),state.selected,status,esc,state.ui.zoom));}
  function advancedSettings(a){return `<div class="advanced-fields"><label class="field">Provider<select disabled aria-label="Provider"><option>Simulation · available</option><option>OpenAI · not connected</option><option>Anthropic · not connected</option><option>Google · not connected</option><option>Local model · not connected</option></select></label><label class="field">Model<select disabled aria-label="Model"><option>Deterministic document extractor</option></select></label><p class="field-help">Memory: each agent has a separate saved conversation and run history. These records are not model memory and are not passed into simulated tasks. Real providers and automatic memory retrieval are not connected. Explicit simulator collaboration is available in Workshop.</p></div>`;}
  function creationDialog(){const c=state.ui.creation;if(!c)return '';const a=c.agent;const phase=c.phase||0;return `<div class="dialog-backdrop"><section class="dialog create-dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="dialog-heading"><div><div class="eyebrow">New identity · existing agents stay unchanged</div><h2 id="dialog-title">Create New Agent</h2></div><button class="link" data-action="close-modal" aria-label="Close and keep draft">×</button></div><div class="creation-progress"><span class="${phase===0?'current':''}">1 · Identity</span><span class="${phase===1?'current':''}">2 · Instructions & tools</span><span class="${phase===2?'current':''}">3 · Review & create</span></div>${liveTutorial()?`<div class="dialog-guidance"><strong>Lesson ${steps[state.tutorial.step]?.lesson||2}: ${steps[state.tutorial.step]?.title||'Create your agent'}</strong><p>${steps[state.tutorial.step]?.text||''}</p></div>`:''}${liveTutorial()?'<div class="guide-controls"><button data-action="skip-step">Skip Step →</button><button data-action="tutorial-help">I’m stuck</button><button data-action="skip-tutorial">Exit tutorial</button></div>':''}<form id="create-form">${phase===0?`<label class="field">Agent name<input id="new-agent-name" name="name" type="text" maxlength="32" required placeholder="e.g. Herman" autocomplete="off" value="${esc(a.name)}"></label>${identity.fields(a,esc)}`:phase===1?`<div class="draft-identity" style="${style(a)}">${bot(a)}<div><strong>${esc(a.name)}</strong><p>New agent draft · not created yet</p></div></div><label class="field">Role<input name="role" type="text" maxlength="80" required value="${esc(a.role)}"></label><label class="field">Instructions<textarea name="instructions" rows="3" maxlength="2000" required>${esc(a.instructions)}</textarea><small>Try “Use bullets.” and “Include risks and uncertainty.” These are supported simulation cues.</small></label><label class="checkbox-row"><input type="checkbox" name="tool" ${a.tool?'checked':''}>Enable Sample document tool</label><p class="field-help">Read-only access to this agent’s sample text. No access to your files or accounts.</p><details class="advanced-settings"><summary>Advanced settings · provider, model & memory</summary>${advancedSettings(a)}</details>`:`<div class="review-agent" style="${style(a)}">${bot(a)}<h3>${a.symbol} ${esc(a.name)}</h3><p>${esc(a.role)}</p></div><dl class="review-list"><dt>Appearance</dt><dd>${esc(identity.shapes.find(x=>x.id===a.avatar).name)} · ${esc(identity.accessories.find(x=>x.id===a.accessory).name)}</dd><dt>Instructions</dt><dd>${esc(a.instructions)}</dd><dt>Tool access</dt><dd>${a.tool?'Sample document · read only':'No tools enabled'}</dd><dt>Execution</dt><dd>Simulation · no API costs</dd></dl><p class="field-help">Create Agent adds a new workstation and saves this agent independently. It does not rename or replace Moss or anyone else.</p>`}<p id="create-error" class="error-inline" role="alert"></p><div class="form-actions"><button type="button" data-action="${phase?'create-back':'close-modal'}">${phase?'Back':'Close · keep draft'}</button><button class="primary" type="submit" id="create-next">${['Continue to instructions →','Review agent →','Create Agent'][phase]}</button></div></form></section></div>`;}

  function workshop(){const a=agent(),r=latest();const msgs=state.messages.filter(m=>m.agentId===a.id&&m.sessionId===a.sessionId);return `<div class="workspace-grid"><div><section class="panel"><div class="panel-head"><h2>Your workshop <span class="muted" style="font-size:11px;font-weight:400;margin-left:8px">${state.agents.filter(a=>a.lifecycle==='active').length} active ${state.agents.length===1?'agent':'agents'}</span></h2><select class="agent-switch" id="agent-select" aria-label="Active agent">${state.agents.map(x=>`<option value="${x.id}" ${x.id===a.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>${room()}<div class="scene-footer"><span><span class="live-dot"></span>Simulation environment</span><label class="zoom-control">Room scale <select id="room-zoom" aria-label="Room scale"><option value="1" ${state.ui.zoom===1?'selected':''}>100%</option><option value="0.85" ${state.ui.zoom===.85?'selected':''}>85%</option><option value="0.7" ${state.ui.zoom===.7?'selected':''}>70%</option></select></label></div><div class="agent-row"><div class="agent-mini">${bot()}</div><div class="agent-info"><h3>${a.symbol} ${esc(a.name)} <small>· Selected agent</small></h3><p>${esc(a.role)} · configuration v${a.version}</p></div><span class="status-tag ${status()}">${status().replace('-',' ')}</span><button class="small" data-view="blueprint">Edit agent</button></div></section><div class="under-workshop"><div class="stat-card"><div class="eyebrow">Learning through doing</div><div class="value">${runs().filter(r=>r.status==='completed').length} <span style="font-size:12px;color:var(--muted)">completed runs</span></div><p>Every run has a trace you can inspect.</p></div><div class="stat-card"><div class="eyebrow">A safe place to experiment</div><div class="value">$0.00 <span style="font-size:12px;color:var(--muted)">API spend</span></div><p>Simulated responses. No API connection.</p></div></div></div><section class="panel chat identity-accent"><div class="panel-head"><div><h2>${a.symbol} Chat with ${esc(a.name)}</h2><div class="sub"><span class="live-dot"></span>${busy()?'Run in progress':'Ready to explore'}</div></div><span class="pill">Simulation</span></div><div class="chat-messages" id="messages" role="log" aria-label="Agent conversation">${msgs.length?msgs.map(m=>`<div class="chat-message ${m.role}"><div class="who">${m.role==='user'?'You':esc(a.name)}${m.role==='agent'?'<span class="sim-label">SIMULATED</span>':''}<span class="time">${time(m.at)}</span></div><div class="message">${esc(m.text)}</div></div>`).join(''):`<div class="empty-chat">${bot()}<h3>Hello, I’m ${esc(a.name)}.</h3><p>Let’s turn a document into something useful. Give me a task and watch how the pieces work together.</p><p>This sandbox uses scripted responses.<br>No model or account is connected.</p></div>`}</div><form id="task-form" class="composer"><div class="prompt-chips"><button type="button" data-prompt="Summarize the sample document">Summarize document</button><button type="button" data-prompt="Create an action checklist from the sample document">Make a checklist</button></div><div class="input-wrap"><textarea id="task-input" aria-label="Task for your agent" placeholder="What would you like to explore?" maxlength="2000" >${esc(chatDraft())}</textarea><div class="send-row"><span>Enter to send · Shift + Enter for a new line</span><button type="submit" class="primary${highlight('send')}" >${busy()?'Queue task':'Run task'} ↑</button></div></div><div class="error-inline" id="task-error" role="alert"></div></form></section></div>${collaborationPanel()}${tutorial()}<section class="panel activity-panel"><div class="panel-head"><h2>${a.symbol} ${esc(a.name)}’s activity</h2><div class="run-controls">${busy()?`<button data-action="${runtime().active.paused?'resume':'pause'}">${runtime().active.paused?'Resume':'Pause'}</button><button data-action="cancel">Cancel</button>`:''}<button class="link small" data-view="laboratory">Open Laboratory ↗</button></div></div><div class="activity-lines">${r?r.events.slice(-4).reverse().map(e=>`<div class="activity-line"><span class="symbol">${e.state==='failed'?'!':e.type==='task.completed'?'✓':'↳'}</span><span>${esc(e.label)}</span><time>${time(e.at)}</time></div>`).join(''):'<div class="activity-line"><span class="symbol">✧</span>Your workshop is ready. Run a task to see what happens.</div>'}</div></section>`;}
  function blueprint(){const a=configDraft()||agent();return `<div class="intro-card">One agent, three perspectives. Changes here configure the agent in your Workshop. The diagram shows the current fixed simulation path; autonomous decisions and editable multi-agent graphs are future integrations.</div><div class="view-grid"><section class="panel"><div class="panel-head"><h2>Edit ${esc(agent().name)}</h2><span class="pill">Version ${agent().version}</span></div><form id="config-form" class="form-body"><div class="edit-notice">Editing this agent preserves its identity and history. Changes apply to future runs.</div>${identity.fields(a,esc)}<label class="field">Role<input name="role" type="text" maxlength="80" required value="${esc(a.role)}"></label><label class="field">Agent name<input type="text" name="name" value="${esc(a.name)}" required maxlength="32"></label><label class="field">Instructions<textarea name="instructions" rows="3" maxlength="2000" required>${esc(a.instructions)}</textarea><small>The simulator recognizes “bullets”, “risk” / “uncertainty”, “next steps”, and “detailed” cues. Other instructions are recorded for inspection, but require a future model to interpret freely.</small></label><button type="button" class="small risk-helper" data-action="add-risk">＋ Add risk review instruction</button><label class="field">Output style<select name="format" class="${highlight('format')}"><option value="concise" ${a.format==='concise'?'selected':''}>Concise · first 3 sentences</option><option value="detailed" ${a.format==='detailed'?'selected':''}>Detailed · first 7 sentences</option></select></label><label class="checkbox-row"><input type="checkbox" name="tool" ${a.tool?'checked':''}>Enable Sample document tool</label><label class="field"><small>Permission: read only the text below. No access to your files or accounts.</small></label><details><summary style="cursor:pointer;font-size:12px;color:var(--muted)">Edit the sample document</summary><label class="field"><textarea name="document" rows="7" maxlength="10000" required>${esc(a.document)}</textarea><small>Use a title, a blank line, then the document body. This text is stored in this browser.</small></label></details><div class="section-space form-actions"><span class="form-dirty" id="dirty-label">${configDraft()?'Unsaved changes · draft kept on this device':'All changes saved'}</span><button class="primary${highlight('config-save')}" type="submit" ${busy()?'disabled':''}>Save Changes</button></div>${formError?`<p class="error-inline" role="alert">${esc(formError)}</p>`:''}</form></section><div><section class="panel"><div class="panel-head"><h2>Execution blueprint</h2><span class="eyebrow">Simulation path</span></div><div class="flow"><div class="node"><div class="eyebrow">01 · Input</div><h3>Your task</h3><p>A natural-language request from the chat.</p></div><div class="connector"></div><div class="node identity-accent"><div class="eyebrow">02 · Agent</div><h3>${agent().symbol} ${esc(agent().name)} · v${agent().version}</h3><p>Instructions + ${esc(agent().format)} output<br>Provider: deterministic simulation</p></div><div class="connector"></div><div class="node"><div class="eyebrow">03 · Tool</div><h3>sample_document.read</h3><p>${agent().tool?'Enabled · read-only local sample':'Disabled · runs will stop with an error'}</p></div><div class="connector"></div><div class="node"><div class="eyebrow">04 · Result</div><h3>Response + execution trace</h3><p>Inspect the output and score it in Laboratory.</p></div></div><div class="info-box">${state.settings.advanced?'The runtime publishes typed events to subscribers. Each run snapshots the agent configuration and uses a provider adapter. A real model adapter can later select tools dynamically; this simulator uses a fixed sequence.':'A chatbot responds to a message. An agent can also use tools to carry out a task. Here, you can see that loop in a predictable simulation. The simulated path is fixed, so it is also a workflow.'}</div></section><section class="panel section-space"><div class="panel-head"><h2>Provider & memory</h2></div><div class="form-body">${advancedSettings(agent())}</div></section><section class="panel section-space"><div class="panel-head"><h2>Practice handling failure</h2></div><div class="form-body"><label class="checkbox-row"><input id="practice-failure" type="checkbox" ${failureNext.has(agent().id)?'checked':''}>Make the next document read fail</label><p class="muted" style="font-size:12px">An intentional, one-time error. Watch the failed state, inspect the error, then retry from Laboratory.</p></div></section></div></div>${tutorial()}`;}
  function trace(r){return r.events.map(e=>`<details class="trace-item${e.type==='tool.result'?highlight('tool-result'):''}" data-event-id="${e.id}" data-event-type="${e.type}" ${openEvents.has(e.id)?'open':''}><summary><span>${esc(e.label)}</span><time>${time(e.at)}</time></summary><pre>${esc(JSON.stringify(state.settings.advanced?{type:e.type,at:e.at,...e.data}:e.data,null,2))}</pre></details>`).join('');}
  function lab(){const r=currentRun();if(!r)return `<section class="panel empty"><h2>Your first experiment starts with a task.</h2><p>Run a task in Workshop, then come here to inspect the trace and evaluate the output.</p><button class="primary" data-view="workshop">Go to Workshop</button></section>${tutorial()}`;const out=r.events.find(e=>e.type==='task.completed')?.data.output;const complete=r.status==='completed';const evaluation=state.drafts.evaluations[r.id]||r.evaluation;return `<div class="metric-row"><div class="metric"><b class="${r.status==='failed'?'danger':''}" style="text-transform:capitalize">${r.status.replace('-',' ')}</b><span>Run status</span></div><div class="metric"><b>${r.events.length}</b><span>Observable events</span></div><div class="metric"><b>$0.00</b><span>Simulation · no model tokens</span></div></div><div class="view-grid"><section class="panel"><div class="panel-head"><h2>${agent().symbol} ${esc(agent().name)}’s execution trace</h2><select id="run-select" class="run-select" aria-label="Select a run">${runs().map((x,i)=>`<option value="${x.id}" ${x.id===r.id?'selected':''}>Run ${runs().length-i} · v${x.config.version} · ${time(x.started)} · ${esc(x.status)}</option>`).join('')}</select></div><div class="info-box">${esc(r.task)}<br><small>Configuration snapshot: ${esc(r.config.name)} v${r.config.version} · ${esc(r.config.format)}</small></div><div class="trace-list">${trace(r)}</div>${['failed','cancelled'].includes(r.status)?'<div class="form-body"><p class="muted" style="font-size:12px;margin-bottom:13px">Check the error above. A disabled tool must be enabled in Blueprint. Intentional practice failures are cleared automatically.</p><button class="primary" data-action="retry" '+(busy()?'disabled':'')+'>Retry with current configuration</button></div>':''}</section><div><section class="panel"><div class="panel-head"><h2>Agent output</h2><span class="pill">Simulated</span></div><details class="output-details" id="output-details" ${openEvents.has('output-'+r.id)?'open':''}><summary>Inspect agent output ${out?'↗':'· waiting for completion'}</summary><div class="output">${out?esc(out):'No completed output yet. The trace shows the current state.'}</div></details></section><section class="panel section-space"><div class="panel-head"><h2>Human evaluation</h2><span class="eyebrow">${r.evaluation?'Saved':'Your judgment matters'}</span></div><form id="evaluation-form" class="form-body"><p class="muted" style="font-size:12px;margin-bottom:15px">Compare the output with the source in “Document received”. Score accuracy and whether it includes the important findings, limitations, and next steps.</p><div class="score-row"><label class="field">Accuracy<select name="accuracy" required ${!complete?'disabled':''}>${['Choose…','1 · Incorrect','2 · Major errors','3 · Some errors','4 · Mostly accurate','5 · Accurate'].map((v,i)=>`<option value="${i||''}" ${Number(evaluation?.accuracy)===i?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Coverage<select name="coverage" required ${!complete?'disabled':''}>${['Choose…','1 · Missing essentials','2 · Limited','3 · Partial','4 · Good','5 · Complete'].map((v,i)=>`<option value="${i||''}" ${Number(evaluation?.coverage)===i?'selected':''}>${v}</option>`).join('')}</select></label></div><label class="field">Review notes<textarea name="notes" rows="2" maxlength="2000" placeholder="What worked? What would you change?" ${!complete?'disabled':''}>${esc(evaluation?.notes||'')}</textarea></label><button type="submit" class="primary${highlight('score')}" ${!complete?'disabled':''}>Save evaluation</button></form></section></div></div><section class="panel section-space"><div class="panel-head"><div><h2>Compare experiments</h2><div class="sub">Completed runs for ${esc(agent().name)} · immutable configuration snapshots</div></div><button class="${highlight('compare')}" data-action="compare" ${runs().filter(r=>r.status==='completed').length<2?'disabled':''}>Compare latest two</button></div><div id="comparison"><div class="info-box">Run the same task with a different output style, then compare the two results here.</div></div></section>${tutorial()}`;}
  function learn(){return `${contextLesson()}<section class="panel form-body"><h2>Practice sandbox</h2><p>Practice agents are labeled in the roster. Reset removes only those fixtures and their records, never your personal agents.</p><button data-action="prepare-practice">Open practice agent</button> <button data-action="reset-experiment">Reset Experiment</button><details><summary>Revisit tutorial actions</summary>${steps.map((step,i)=>`<p><button data-lesson="${i}">${i+1}. ${step.title}</button> · ${state.tutorial.progress?.[i]||'unfinished'}</p>`).join('')}</details></section><div class="guide-controls"><button data-action="restart-tutorial">Replay introductory tutorial</button><button data-action="toggle-tutorials">${state.settings.tutorialDisabled?'Enable tutorials':'Disable all tutorials'}</button><button data-action="import">Import workshop backup</button></div><div class="lesson-list"><section class="panel lesson"><span class="number">01 / INTERACTIVE TUTORIAL</span><h2>Your first agent</h2><p>Build a document explorer, watch it use a tool, inspect its trace, and evaluate the result. Learn through real interface actions in a safe simulation.</p><button class="primary" data-action="${state.tutorial.step>=steps.length?'restart-tutorial':state.tutorial.step>0?'continue-tutorial':'start-tutorial'}">${state.tutorial.step>=steps.length?'Replay tutorial':state.tutorial.step>0?'Continue tutorial':'Start tutorial'} ↗</button></section><section class="panel lesson"><span class="number">02 / EXPERIMENT</span><h2>When a tool fails</h2><p>Turn on a practice failure in Blueprint, run a task, and inspect the error in Laboratory. Retry to recover. Failure is an observable state you can diagnose.</p><button data-action="failure-lesson">Try a practice failure</button></section><section class="panel lesson"><span class="number">CONCEPT / CONTEXT & MEMORY</span><h2>What does an agent remember?</h2><p>This prototype stores chat history in your browser, but each simulated run reads only its task, saved instructions, and sample document. Stored conversation is not automatically model context or long-term memory.</p></section><section class="panel lesson"><span class="number">CONCEPT / WORKFLOWS & AGENTS</span><h2>Who chooses the next step?</h2><p>A workflow follows predefined steps. A model-driven agent can choose actions based on observations. This prototype demonstrates the execution loop with fixed steps; model decisions require a future integration. Try the recorded Research → Evaluation handoff in Workshop.</p></section></div>${tutorial()}`;}
  function render(){
    const focused=document.activeElement;const focusId=focused?.id;const focusName=focused?.name;const focusForm=focused?.closest('form')?.id;const caret=typeof focused?.selectionStart==='number'?[focused.selectionStart,focused.selectionEnd]:null;
    const roomScroll=document.querySelector('.room-scroll');const scroll=roomScroll?[roomScroll.scrollLeft,roomScroll.scrollTop]:null;
    const labels={workshop:['The Workshop','Your agents. Your experiments. A shared headquarters.'],blueprint:[`Edit ${agent().name}`,'Your selected agent’s identity, instructions, and tools.'],laboratory:['The Laboratory','Observe what happened. Understand what to improve.'],learn:['Field guide','Small experiments. Practical understanding.'],roster:['Agent Roster','Persistent identities. Roles that can evolve.'],queue:['Task queue','Explicit assignments. Predictable execution.'],sessions:['Sessions & memory','Keep useful context. Start fresh without losing your agent.'],settings:['Settings','One workspace. Three atmospheres.']};const l=labels[view];
    document.getElementById('app').innerHTML=`<div class="shell" style="${style()}"><aside class="sidebar"><div class="brand"><span class="brand-icon">❋</span><span class="brand-text">AI Agent<br>Workshop</span></div><div class="rainbow-stripe" aria-hidden="true"></div><div class="sidebar-label">YOUR CREATIVE SPACE</div><nav class="nav" aria-label="Main navigation">${Object.keys(labels).map(v=>`<button data-view="${v}" title="${v==='blueprint'?'Blueprint':labels[v][0]}" class="${v===view?'active':''}" ${v===view?'aria-current="page"':''}>${icon(v)}<span class="nav-text">${v==='learn'?'Field guide':v==='blueprint'?'Blueprint':labels[v][0].replace('The ','')}</span></button>`).join('')}</nav><div class="side-bottom"><div class="sandbox-card"><span class="live-dot"></span><span style="font-size:12px">Simulation mode</span><p>A safe place to learn.<br>No API keys. No costs.</p></div><button class="link small" data-action="export">↓ Export workshop</button><button class="link small" data-action="import">↑ Import backup</button><div class="profile"><span class="initial">✦</span><div>Your workspace<br><small>${state.agents.filter(a=>a.lifecycle==='active').length} active agents</small></div></div></div></aside><main class="main"><header class="topbar"><span>Workspace <span style="margin:0 9px">/</span> ${esc(l[0].replace('The ',''))}</span><div class="right"><span class="pill"><span class="live-dot"></span>Simulation mode</span><button class="link small" data-action="explanation">${state.settings.advanced?'Advanced explanations':'Beginner explanations'} ⌄</button><button class="link small" data-view="learn" aria-label="Open field guide">ⓘ</button></div></header><div class="page-heading"><div><h1>${esc(l[0])}</h1><p>${l[1]}</p></div>${view==='workshop'?'<button class="primary" data-action="new-agent">＋ New agent</button>':view!=='learn'?`<span class="selected-identity" style="${style()}">${agent().symbol} ${esc(agent().name)}</span>`:''}</div>${state.ui.notice?`<div class="success-banner" role="status">✓ ${esc(state.ui.notice)} <button class="link small" data-action="dismiss-notice" aria-label="Dismiss confirmation">×</button></div>`:''}${({workshop,blueprint,laboratory:()=>sharedTimeline()+lab(),learn,roster,queue:queueView,sessions:sessionView,settings:settingsView})[view]()}<footer class="footer-note"><span>Made for curiosity. Room for every agent.</span><span>${storageOK?'● Saved in this browser':'Storage unavailable — keep this tab open and export your data'} · Neon review 0.2.0</span></footer></main></div>${modal?creationDialog():''}<input id="import-file" type="file" accept="application/json,.json" hidden>`;
    bind();applyHighlights();renderConnections();if(comparisonVisible&&view==='laboratory')showComparison();
    const messages=document.getElementById('messages');if(messages)messages.scrollTop=messages.scrollHeight;
    if(scroll&&document.querySelector('.room-scroll')){document.querySelector('.room-scroll').scrollLeft=scroll[0];document.querySelector('.room-scroll').scrollTop=scroll[1];}
    const target=focusId?document.getElementById(focusId):focusName&&focusForm?document.querySelector(`#${focusForm} [name="${focusName}"]`):null;
    if(target){target.focus({preventScroll:true});if(caret&&target.setSelectionRange&&['text','textarea'].includes(target.type))target.setSelectionRange(...caret);}
  }
  function go(next){view=next;state.ui.view=next;formError='';if(next==='laboratory'&&liveTutorial()&&state.tutorial.step===5&&state.selected===state.tutorial.agentId&&latest()?.events.length){selectedRun=state.tutorial.baseline;advance('observe','You opened this agent’s real execution events.');}save();render();window.scrollTo({top:0,behavior:'instant'});}
  function selectAgent(id){if(!state.agents.some(a=>a.id===id))return;state.selected=id;selectedRun=null;comparisonVisible=false;if(liveTutorial()&&state.tutorial.step===0&&id===state.tutorial.starterId)advance('meet','Moss is selected. Creating another agent will leave Moss unchanged.');save();render();document.getElementById('task-input')?.focus({preventScroll:true});}
  function beginTask(task){if(agent().lifecycle!=='active'){toast('Return this agent to the Workshop from the roster first.');return;}task=task.trim();if(!task){const err=document.getElementById('task-error');if(err)err.textContent='Add a task first, or choose one of the examples.';return;}
    if(liveTutorial()&&state.tutorial.step===9&&agent().id===state.tutorial.agentId){const base=state.runs.find(r=>r.id===state.tutorial.baseline);if(base&&task!==base.task){toast('This task will run normally. The tutorial comparison still needs the original task.');}}
    const a=agent();const run=data.enqueue(state,a,task);
    state.messages.push({id:uid(),agentId:a.id,role:'user',text:task,at:run.started,sessionId:run.sessionId});state.drafts.chats[a.id]='';selectedRun=run.id;comparisonVisible=false;view='workshop';state.ui.view=view;
    if(liveTutorial()&&state.tutorial.agentId===a.id){if(state.tutorial.step===4){state.tutorial.baseline=run.id;advance('assign',`${a.name} received a task. Moss and the others keep their own states.`);}else if(state.tutorial.step===9&&state.runs.find(r=>r.id===state.tutorial.baseline)?.task===task){state.tutorial.revisedRun=run.id;advance('rerun','The same task is running with your revised instructions.');}}
    run.fail=failureNext.has(a.id);failureNext.delete(a.id);save();pump(a.id);render();
  }
  function onRuntimeEvent(event){const r=state.runs.find(r=>r.id===event.runId);if(!r)return;r.events.push({...event,agentId:r.agentId});r.status=event.state;
    if(['completed','failed','cancelled'].includes(event.state)){r.finished=event.at;state.messages.push({id:uid(),agentId:r.agentId,role:'agent',text:event.type==='task.completed'?event.data.output:event.data.error||event.data.message||'Task cancelled. You can start a fresh run.',at:event.at,sessionId:r.sessionId});
      if(liveTutorial()&&r.agentId===state.tutorial.agentId&&event.type==='task.completed'&&state.tutorial.step===10&&state.selected===r.agentId){view='laboratory';state.ui.view=view;selectedRun=r.id;}
    }
    if(data.terminal(r.status))setTimeout(()=>{finishHandoff(r);pump(r.agentId);save();render();},0);
    save();setTimeout(render,0);
  }

  function comparisonRuns(){const completed=runs().filter(r=>r.status==='completed');return completed.slice(0,2).reverse();}
  function showComparison(){const two=comparisonRuns();const el=document.getElementById('comparison');if(!el||two.length<2)return;el.innerHTML=`<div class="compare-grid" style="padding:18px">${two.map((r,i)=>`<div class="panel" style="${style(r.config)}"><div class="panel-head"><h2>${i?'After':'Before'} · v${r.config.version}</h2><span class="pill">${esc(r.config.format)}</span></div><div class="info-box"><strong>Saved instructions</strong><br>${esc(r.config.instructions)}</div><div class="output">${esc(r.events.find(e=>e.type==='task.completed').data.output)}</div><div class="info-box">${r.evaluation?`Human score: accuracy ${r.evaluation.accuracy}/5 · coverage ${r.evaluation.coverage}/5`:'Not scored yet'}</div></div>`).join('')}</div>`;}
  function compare(){const two=comparisonRuns();if(two.length<2)return;const t=state.tutorial;if(liveTutorial()&&t.step===10&&agent().id===t.agentId){if(two[1].id===t.revisedRun&&two[0].id===t.baseline&&two[1].task===two[0].task)advance('compare','Tutorial complete. You created, observed, evaluated, and improved your own agent.');else toast('Compare the original tutorial task with its revised run.');}comparisonVisible=true;render();document.getElementById('comparison')?.scrollIntoView({behavior:'smooth',block:'center'});}
  function readForm(form,base){const f=new FormData(form);const next={...base};for(const key of ['name','role','instructions','format','document','avatar','accessory','color','symbol'])if(f.has(key))next[key]=String(f.get(key));if(form.querySelector('[name="tool"]'))next.tool=f.get('tool')==='on';return identity.normalize(next);}
  function rememberForm(form){if(form.id==='create-form'){const c=state.ui.creation;c.agent=readForm(form,c.agent);}else state.drafts.agents[agent().id]=readForm(form,configDraft()||agent());save();const label=document.getElementById('dirty-label');if(label)label.textContent='Unsaved changes · draft kept on this device';updateAppearance(form);applyHighlights();}
  function updateAppearance(form){const a=form.id==='create-form'?state.ui.creation.agent:configDraft()||agent();const preview=form.querySelector('.avatar-preview');if(preview){preview.style.cssText=style(a);preview.innerHTML=bot(a)+'<span>Appearance preview</span>';}form.querySelectorAll('[data-color]').forEach(b=>{const chosen=b.dataset.color.toLowerCase()===a.color.toLowerCase();b.classList.toggle('chosen',chosen);b.setAttribute('aria-pressed',chosen);b.textContent=chosen?'✓':'';});}
  function startTutorial(){if(state.ui.creation&&!state.ui.creation.practice){state.ui.savedCreation=state.ui.creation;state.ui.creation=null;}state.settings.tutorialDisabled=false;let starter=state.agents.find(a=>a.practice&&a.name==='Practice Moss');if(!starter){starter=makeAgent('Practice Moss');starter.practice=true;starter.lifecycle='active';state.agents.push(starter);ensureSession(starter);}state.tutorial={schema:2,active:true,paused:false,step:0,progress:{},starterId:starter.id};starter.lifecycle='active';state.selected=starter.id;modal=false;if(state.ui.creation?.practice)state.ui.creation.phase=0;save();go('workshop');}
  function guide(){const t=state.tutorial;const step=steps[t.step];if(!step)return;state.settings.tutorialDisabled=false;t.active=true;t.paused=false;if(t.step===0&&state.agents.some(a=>a.id===t.starterId))state.selected=t.starterId;else if(state.agents.some(a=>a.id===t.agentId))state.selected=t.agentId;t.help=true;modal=!!state.ui.creation&&t.step>=1&&t.step<=3;go(step.view);const el=document.querySelector('.highlight');el?.scrollIntoView({behavior:'smooth',block:'center'});}
  function applyHighlights(){document.querySelectorAll('.highlight').forEach(el=>el.classList.remove('highlight'));if(!liveTutorial())return;const t=state.tutorial;let target='';const c=state.ui.creation;
    if(t.step===0)target=`[data-select-agent="${t.starterId}"]`;
    if(t.step===1){if(!modal)target='[data-action="new-agent"]';else if(!c.agent.name.trim())target='#new-agent-name';else if(!c.chosenAvatar)target='#create-form [name="avatar"]';else if(!c.chosenColor)target='#create-form .color-field';else target='#create-next';}
    if(t.step===2)target=modal?(c?.instructionsEdited?'#create-next':'#create-form [name="instructions"]'):'[data-action="new-agent"]';
    if(t.step===3)target=modal?'#create-next':'[data-action="new-agent"]';
    if([4,9].includes(t.step))target=chatDraft().trim()?'#task-form button[type="submit"]':'[data-prompt="Summarize the sample document"]';
    if(t.step===5)target='.activity-panel [data-view="laboratory"]';
    if(t.step===6)target='#output-details > summary';
    if(t.step===7){const f=document.getElementById('evaluation-form');target=!f?.elements.accuracy.value?'[name="accuracy"]':!f?.elements.coverage.value?'[name="coverage"]':'#evaluation-form button[type="submit"]';}
    if(t.step===8)target=configDraft()?.instructions!==undefined&&configDraft().instructions!==agent().instructions?'#config-form button[type="submit"]':'[data-action="add-risk"]';
    if(t.step===10)target='[data-action="compare"]';
    const element=target?document.querySelector(target):null;if(element)element.classList.add('highlight');else{const nav=document.querySelector(`[data-view="${steps[t.step]?.view}"]`);nav?.classList.add('highlight');}
  }
  function finishCreation(){const c=state.ui.creation;const a=c.agent;const err=document.getElementById('create-error');if(c.phase===0){if(!a.name.trim()){err.textContent='Give your new agent a name.';return;}if(liveTutorial()&&state.tutorial.step===1&&(!c.chosenAvatar||!c.chosenColor)){err.textContent='Choose an avatar shape and a color to make this new agent recognizable.';applyHighlights();return;}c.phase=1;advance('identity','Your new identity is drafted. No existing agent has changed.');}
    else if(c.phase===1){if(!a.role.trim()||!a.instructions.trim()){err.textContent='Add a role and instructions before reviewing.';return;}if(liveTutorial()&&state.tutorial.step===2&&!a.tool){err.textContent='Enable the Sample document tool for this tutorial task.';return;}c.phase=2;advance('configure','Instructions and read-only tool access are ready. Review before creating.');}
    else {a.name=a.name.trim();a.instructions=a.instructions.trim();if(liveTutorial()&&state.tutorial.step>=1&&state.tutorial.step<=3)a.practice=true;state.agents.push(a);a.lifecycle='active';state.versions[a.id]=[structuredClone(a)];ensureSession(a);state.selected=a.id;selectedRun=null;if(liveTutorial()&&state.tutorial.step===3){state.tutorial.agentId=a.id;advance('create',`${a.name} now has a separate workstation and history.`);}state.ui.creation=null;modal=false;state.ui.notice=`${a.name} has joined your Workshop!`;save();go('workshop');toast(state.ui.notice);return;}save();render();document.querySelector('#create-form input,#create-form textarea,#create-next')?.focus();
  }

  function bind(){
    bindManagement();
    document.querySelectorAll('[data-lesson]').forEach(el=>el.onclick=()=>{state.tutorial.step=Number(el.dataset.lesson);state.tutorial.active=true;guide();});
    document.querySelectorAll('[data-view]').forEach(el=>el.onclick=()=>go(el.dataset.view));
    document.querySelectorAll('[data-select-agent]').forEach(el=>el.onclick=()=>selectAgent(el.dataset.selectAgent));
    document.querySelectorAll('[data-prompt]').forEach(el=>el.onclick=()=>{state.drafts.chats[agent().id]=el.dataset.prompt;save();const input=document.getElementById('task-input');input.value=chatDraft();input.focus();applyHighlights();});
    document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{switch(el.dataset.action){
      case'new-agent':if(!state.ui.creation){const fresh=makeAgent('',state.agents.length);const used=new Set(state.agents.map(a=>a.color));const preferred=identity.palette.find(c=>!used.has(c.value)&&c.value===identity.defaults('',state.agents.length).color)||identity.palette.find(c=>!used.has(c.value));if(preferred)fresh.color=preferred.value;state.ui.creation={agent:fresh,phase:0,chosenAvatar:false,chosenColor:false,practice:liveTutorial()&&state.tutorial.step>=1&&state.tutorial.step<=3};}modal=true;save();render();document.getElementById('new-agent-name')?.focus();break;
      case'close-modal':modal=false;render();break;
      case'create-back':state.ui.creation.phase=Math.max(0,state.ui.creation.phase-1);if(liveTutorial()&&state.tutorial.step>1&&state.tutorial.step<=3)state.tutorial.step--;save();render();break;
      case'dismiss-notice':state.ui.notice='';save();render();break;
      case'start-tutorial':case'restart-tutorial':startTutorial();break;
      case'continue-tutorial':case'guide-me':guide();break;
      case'tutorial-help':state.tutorial.help=true;modal=false;save();guide();break;
      case'tutorial-back':state.tutorial.step=Math.max(0,state.tutorial.step-1);state.tutorial.lastSuccess='Revisiting a previous action.';modal=false;guide();break;
      case'tutorial-next':if(state.tutorial.progress?.[state.tutorial.step])state.tutorial.step++;modal=false;save();render();break;
      case'skip-step':{const t=state.tutorial;t.progress||={};if(t.progress[t.step]!=='completed')t.progress[t.step]='skipped';t.step=Math.min(steps.length,t.step+1);t.lastSuccess='Action skipped, not marked completed.';t.help=true;modal=false;save();render();break;}
      case'prepare-practice':preparePractice();break;
      case'reset-experiment':resetExperiment();break;
      case'pause-tutorial':state.tutorial.paused=true;save();render();break;
      case'skip-tutorial':modal=false;if(state.ui.savedCreation){state.ui.creation=state.ui.savedCreation;delete state.ui.savedCreation;}state.tutorial.active=false;state.tutorial.paused=true;save();render();break;
      case'toggle-tutorials':state.settings.tutorialDisabled=!state.settings.tutorialDisabled;save();render();break;
      case'explanation':state.settings.advanced=!state.settings.advanced;save();render();break;
      case'pause':runtime().pause();break;case'resume':runtime().resume();break;case'cancel':runtime().cancel();break;
      case'retry':retryRun(currentRun());break;case'compare':compare();break;
      case'failure-lesson':preparePractice();failureNext.add(agent().id);go('blueprint');toast(`Practice failure enabled for ${agent().name}’s next run.`);break;
      case'add-risk':{const form=document.getElementById('config-form');const input=form.elements.instructions;if(!/risk|uncertain|limitation/i.test(input.value))input.value=input.value.trim()+' Include risks and uncertainty.';else if(!/next steps?/i.test(input.value))input.value=input.value.trim()+' Include next steps.';else input.value=input.value.trim()+' Provide a detailed summary.';rememberForm(form);input.focus();break;}
      case'export':{const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='ai-agent-workshop.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}
      case'import':document.getElementById('import-file').click();break;
    }});
    document.querySelectorAll('[data-color]').forEach(el=>el.onclick=()=>{const form=el.closest('form');form.elements.color.value=el.dataset.color;if(form.id==='create-form')state.ui.creation.chosenColor=true;rememberForm(form);});
    const create=document.getElementById('create-form');if(create){create.oninput=e=>{if(e.target.name==='avatar')state.ui.creation.chosenAvatar=true;if(e.target.name==='color')state.ui.creation.chosenColor=true;if(e.target.name==='instructions')state.ui.creation.instructionsEdited=true;rememberForm(create);};create.onchange=create.oninput;create.onsubmit=e=>{e.preventDefault();rememberForm(create);finishCreation();};}
    const config=document.getElementById('config-form');if(config){config.oninput=()=>rememberForm(config);config.onchange=config.oninput;config.onsubmit=e=>{e.preventDefault();const updated=readForm(config,agent());if(!updated.name.trim()||!updated.role.trim()||!updated.instructions.trim()||!updated.document.trim()){formError='Name, role, instructions, and sample document cannot be blank.';render();return;}const t=state.tutorial;const oldInstructions=agent().instructions;data.version(state,agent(),{...updated,name:updated.name.trim()});delete state.drafts.agents[agent().id];state.ui.notice=`Changes saved for ${agent().name}. Identity and history preserved.`;if(liveTutorial()&&t.step===8&&agent().id===t.agentId){if(oldInstructions!==agent().instructions&&/risk|uncertain|limitation|next step|detailed/i.test(agent().instructions)){advance('improve','Instructions updated. The original run still has its original configuration.');state.drafts.chats[agent().id]=state.runs.find(r=>r.id===t.baseline)?.task||'Summarize the sample document';save();go('workshop');return;}else toast('For this experiment, add a risk or uncertainty instruction so the simulator’s output changes.');}save();render();toast(state.ui.notice);};}
    document.getElementById('task-form')?.addEventListener('submit',e=>{e.preventDefault();beginTask(document.getElementById('task-input').value);});
    const input=document.getElementById('task-input');if(input){input.oninput=()=>{state.drafts.chats[agent().id]=input.value;save();applyHighlights();};input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();beginTask(input.value);}};}
    document.getElementById('agent-select')?.addEventListener('change',e=>selectAgent(e.target.value));
    document.getElementById('room-zoom')?.addEventListener('change',e=>{state.ui.zoom=Number(e.target.value);save();render();});
    document.getElementById('run-select')?.addEventListener('change',e=>{selectedRun=e.target.value;render();});
    document.getElementById('practice-failure')?.addEventListener('change',e=>{if(e.target.checked)failureNext.add(agent().id);else failureNext.delete(agent().id);});
    document.querySelectorAll('.trace-item').forEach(el=>el.addEventListener('toggle',()=>{if(!el.isConnected)return;if(el.open)openEvents.add(el.dataset.eventId);else openEvents.delete(el.dataset.eventId);}));
    const output=document.getElementById('output-details');if(output)output.ontoggle=()=>{if(!output.isConnected)return;const r=currentRun();if(!r)return;if(output.open){openEvents.add('output-'+r.id);if(r.status==='completed'&&r.id===state.tutorial.baseline&&advance('inspect','You inspected the completed output. Now evaluate it against the source.'))render();}else openEvents.delete('output-'+r.id);};
    const evaluation=document.getElementById('evaluation-form');if(evaluation){evaluation.oninput=()=>{const f=new FormData(evaluation);state.drafts.evaluations[currentRun().id]={accuracy:f.get('accuracy'),coverage:f.get('coverage'),notes:f.get('notes')};save();applyHighlights();};evaluation.onchange=evaluation.oninput;evaluation.onsubmit=e=>{e.preventDefault();const f=new FormData(evaluation);const accuracy=Number(f.get('accuracy')),coverage=Number(f.get('coverage'));if(!accuracy||!coverage||currentRun().status!=='completed'){toast('Choose both scores for a completed run.');return;}currentRun().evaluation={accuracy,coverage,notes:f.get('notes'),at:new Date().toISOString()};delete state.drafts.evaluations[currentRun().id];if(currentRun().id===state.tutorial.baseline&&advance('score','Evaluation saved. Next, change one instruction and repeat the experiment.')){save();go('blueprint');}else{save();render();toast('Evaluation saved with this agent’s run.');}};}
    document.getElementById('import-file')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10000000)throw Error('Backup is too large (maximum 10 MB).');const data=JSON.parse(await file.text());importBackup(data);}catch(error){toast('Could not import: '+error.message);}});
    if(modal){const dialog=document.querySelector('.dialog');dialog.onkeydown=e=>{if(e.key==='Escape'){modal=false;render();}if(e.key==='Tab'){const items=[...dialog.querySelectorAll('input:not([disabled]),textarea,select:not([disabled]),button,summary')].filter(x=>!x.closest('details:not([open])')||x.tagName==='SUMMARY');const at=items.indexOf(document.activeElement);if(e.shiftKey&&at===0){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&at===items.length-1){e.preventDefault();items[0].focus();}}};}
  }
  function importBackup(data){
    if(!Array.isArray(data.agents)||!Array.isArray(data.runs)||!Array.isArray(data.messages)||data.agents.length>200||data.runs.length>16000||data.messages.length>40000)throw Error('Choose a valid Workshop JSON export.');
    const validId=x=>typeof x==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(x)&&!['__proto__','constructor','prototype'].includes(x);
    const validText=(x,max=10000)=>typeof x==='string'&&x.length<=max;
    const validDate=x=>typeof x==='string'&&Number.isFinite(Date.parse(x));
    const statuses=['idle','queued','working','using-tool','completed','failed','cancelled','paused','waiting'];
    function cleanAgent(item,index){if(!item||!validId(item.id)||!validText(item.name,32)||!item.name.trim()||!validText(item.instructions,2000)||!validText(item.document)||!validText(item.role||'Document explorer',80))throw Error('The backup contains an invalid agent.');return identity.normalize({id:item.id,name:item.name,role:item.role||'Document explorer',instructions:item.instructions,document:item.document,tool:item.tool===true,format:item.format==='detailed'?'detailed':'concise',version:Number.isInteger(item.version)&&item.version>0?item.version:1,color:item.color,avatar:item.avatar,accessory:item.accessory,symbol:item.symbol,lifecycle:['active','resting','archived'].includes(item.lifecycle)?item.lifecycle:'active',practice:item.practice===true,sessionId:validId(item.sessionId)?item.sessionId:null},index);}
    // Validate every record before mutating local data. IDs remain safe in DOM attributes.
    const cleanAgents=data.agents.map(cleanAgent);const importedIds=new Set(cleanAgents.map(a=>a.id));if(importedIds.size!==cleanAgents.length)throw Error('Duplicate agent IDs in the backup.');
    const cleanRuns=data.runs.map(item=>{if(!item||!validId(item.id)||!importedIds.has(item.agentId)||!validText(item.task,2000)||!validDate(item.started)||!statuses.includes(item.status)||!Array.isArray(item.events)||item.events.length>2000)throw Error('The backup contains an invalid run.');const config=cleanAgent(item.config,0);if(config.id!==item.agentId)throw Error('A run has a mismatched agent configuration.');
      const events=item.events.map(e=>{if(!e||!validId(e.id)||!validDate(e.at)||!validText(e.type,100)||!/^[a-zA-Z0-9_.-]+$/.test(e.type)||!validText(e.label,500)||!statuses.includes(e.state)||!e.data||typeof e.data!=='object'||Array.isArray(e.data))throw Error('The backup contains an invalid execution event.');return {id:e.id,runId:item.id,agentId:item.agentId,at:e.at,type:e.type,state:e.state,label:e.label,data:e.data};});
      let evaluation=null;if(item.evaluation){const e=item.evaluation;if(![1,2,3,4,5].includes(Number(e.accuracy))||![1,2,3,4,5].includes(Number(e.coverage))||!validText(e.notes||'',2000))throw Error('The backup contains an invalid evaluation.');evaluation={accuracy:Number(e.accuracy),coverage:Number(e.coverage),notes:e.notes||'',at:e.at};}
      const copy={id:item.id,agentId:item.agentId,task:item.task,config,status:item.status,started:item.started,created:validDate(item.created)?item.created:item.started,finished:validDate(item.finished)?item.finished:null,events,evaluation,queueOrder:Number.isFinite(item.queueOrder)?item.queueOrder:0};for(const key of ['sessionId','workflowId','workflowRecipient','handoffId','sentHandoff','retryOf'])if(item[key]!=null){if(!validId(item[key]))throw Error('Invalid task reference.');copy[key]=item[key];}if(item.input)copy.input=cleanPayload(item.input);if(item.context)copy.context=cleanContext(item.context);if(['working','using-tool','paused','waiting'].includes(copy.status)){copy.status='cancelled';copy.events.push({id:uid(),type:'task.interrupted',state:'cancelled',at:new Date().toISOString(),label:'Imported unfinished run',data:{message:'An exported run cannot continue execution. Start a new task.'}});}return copy;
    });
    const cleanMessages=data.messages.map(m=>{if(!m||!validId(m.id)||!importedIds.has(m.agentId)||!validText(m.text,20000)||!validDate(m.at)||!['user','agent'].includes(m.role))throw Error('The backup contains an invalid conversation.');return {id:m.id,agentId:m.agentId,role:m.role,text:m.text,at:m.at,sessionId:validId(m.sessionId)?m.sessionId:null};});
    function cleanPayload(p){if(!p||p.kind!=='research.result'||!validId(p.sourceTaskId)||!validText(p.output,40000)||!validText(p.sourceDocument)||!validText(p.assignment,2000))throw Error('Invalid research payload.');return {schema:1,kind:p.kind,simulated:true,sourceTaskId:p.sourceTaskId,assignment:p.assignment,output:p.output,sourceDocument:p.sourceDocument,configurationVersion:Number(p.configurationVersion)||1};}
    function cleanContext(items){if(!Array.isArray(items)||items.length>1000)throw Error('Invalid context list.');return items.map(c=>{if(!validId(c.sourceId)||!validText(c.text,4000)||!['memory','session-summary'].includes(c.kind))throw Error('Invalid context entry.');return {sourceId:c.sourceId,text:c.text,kind:c.kind};});}
    function records(key,limit){const items=data[key]||[];if(!Array.isArray(items)||items.length>limit)throw Error('Invalid '+key+' list.');return items;}
    const cleanSessions=records('sessions',10000).map(s=>{if(!validId(s.id)||!importedIds.has(s.agentId)||!validText(s.title,200)||!validText(s.summary||'',4000)||!validDate(s.created))throw Error('Invalid session.');return {id:s.id,agentId:s.agentId,title:s.title,summary:s.summary||'',created:s.created,context:cleanContext(s.context||[])};});
    for(const a of cleanAgents){const session=cleanSessions.find(s=>s.id===a.sessionId);if(session&&session.agentId!==a.id)throw Error('Session belongs to a different agent.');}
    const cleanMemories=records('memories',20000).map(m=>{if(!validId(m.id)||!importedIds.has(m.agentId)||!validText(m.text,4000)||!validDate(m.created))throw Error('Invalid memory.');return {id:m.id,agentId:m.agentId,text:m.text,created:m.created};});
    const cleanVersions={};for(const a of cleanAgents){const versions=data.versions?.[a.id]||[a];if(!Array.isArray(versions)||versions.length>2000)throw Error('Invalid configuration history.');cleanVersions[a.id]=versions.map(v=>{const c=cleanAgent(v,0);if(c.id!==a.id)throw Error('Mismatched configuration version.');return c;});}
    const cleanHandoffs=records('handoffs',10000).map(h=>{
      if(!['id','workflowId','senderId','recipientId','senderRunId','recipientRunId'].every(k=>validId(h[k]))||!importedIds.has(h.senderId)||!importedIds.has(h.recipientId)||!validText(h.senderName,32)||!validText(h.recipientName,32)||!validDate(h.at)||!validDate(h.receivedAt)||!['delivered','processed','failed','cancelled','queued'].includes(h.status)||!validText(h.error||'',2000))throw Error('Invalid handoff.');
      const sender=cleanRuns.find(r=>r.id===h.senderRunId&&r.agentId===h.senderId),recipient=cleanRuns.find(r=>r.id===h.recipientRunId&&r.agentId===h.recipientId);if(!sender||!recipient)throw Error('Handoff references a missing task.');
      return {id:h.id,workflowId:h.workflowId,senderId:h.senderId,recipientId:h.recipientId,senderName:h.senderName,recipientName:h.recipientName,senderRunId:h.senderRunId,recipientRunId:h.recipientRunId,at:h.at,receivedAt:h.receivedAt,processedAt:validDate(h.processedAt)?h.processedAt:null,type:'research.result',payload:cleanPayload(h.payload),status:['cancelled','failed'].includes(recipient.status)?recipient.status:h.status,retries:Math.max(0,Number(h.retries)||0),error:h.error||null};
    });
    for(const list of [cleanRuns,cleanSessions,cleanMemories,cleanHandoffs])if(new Set(list.map(x=>x.id)).size!==list.length)throw Error('Duplicate record IDs in backup.');
    const added=new Set(cleanAgents.filter(a=>!state.agents.some(local=>local.id===a.id)).map(a=>a.id));state.agents.push(...cleanAgents.filter(a=>added.has(a.id)));
    state.runs.push(...cleanRuns.filter(r=>added.has(r.agentId)&&!state.runs.some(local=>local.id===r.id)));state.runs.sort((a,b)=>new Date(b.started)-new Date(a.started));
    state.messages.push(...cleanMessages.filter(m=>added.has(m.agentId)&&!state.messages.some(local=>local.id===m.id)));
    state.sessions.push(...cleanSessions.filter(s=>added.has(s.agentId)&&!state.sessions.some(x=>x.id===s.id)));
    state.memories.push(...cleanMemories.filter(m=>added.has(m.agentId)&&!state.memories.some(x=>x.id===m.id)));
    state.handoffs.push(...cleanHandoffs.filter(h=>added.has(h.senderId)&&added.has(h.recipientId)&&!state.handoffs.some(x=>x.id===h.id)));
    for(const a of state.agents.filter(a=>added.has(a.id))){state.versions[a.id]=cleanVersions[a.id];state.queuePaused[a.id]=true;ensureSession(a);for(const r of state.runs.filter(r=>r.agentId===a.id))r.sessionId ||= a.sessionId;for(const m of state.messages.filter(m=>m.agentId===a.id))m.sessionId ||= a.sessionId;}
    state.ui.notice=`Imported ${added.size} agents. Existing identities and histories were kept unchanged.`;save();go('workshop');toast(state.ui.notice);
  }
  // A queue dispatches only explicit assignments, one runtime per agent.
  function pump(id){
    const a=state.agents.find(a=>a.id===id);
    if(!a||a.lifecycle!=='active'||state.queuePaused[id]||busy(id))return;
    const r=data.pending(state,id)[0];if(!r)return;
    r.started=data.now();r.context=structuredClone(state.sessions.find(s=>s.id===r.sessionId)?.context||[]);
    data.event(r,'context.attached','Explicit context snapshot',{items:r.context,usage:'Recorded for inspection; the extractor reads the configured document. No model token usage.'});
    save();runtime(id).start(r.id,r.config,r.task,r.fail,r.input);
  }
  function retryRun(r){
    if(!r||!['failed','cancelled'].includes(r.status))return;
    const a=state.agents.find(a=>a.id===r.agentId);if(a.lifecycle!=='active'){toast('Restore this agent in the roster before retrying.');return;}
    const copy=data.enqueue(state,a,r.task,{retryOf:r.id,input:r.input,workflowId:r.workflowId,handoffId:r.handoffId});
    if(r.handoffId){const h=state.handoffs.find(h=>h.id===r.handoffId);if(h){h.recipientRunId=copy.id;h.status='delivered';h.retries++;h.error=null;}}
    save();pump(a.id);selectedRun=copy.id;go('queue');
  }
  function ensureSession(a){
    a.lifecycle ||= 'active';
    if(!state.sessions.some(s=>s.id===a.sessionId)){
      const session={id:uid(),agentId:a.id,title:'Session 1',created:data.now(),summary:'',context:[]};state.sessions.push(session);a.sessionId=session.id;
    }
    state.versions[a.id] ||= [structuredClone(a)];
  }
  function roster(){
    const filter=state.ui.rosterFilter||'all',search=(state.ui.rosterSearch||'').toLowerCase();
    const list=state.agents.filter(a=>(filter==='all'||a.lifecycle===filter)&&(a.name+' '+a.role+' '+status(a.id)).toLowerCase().includes(search));
    return `<div class="guide-controls"><label class="field">Search name, role, or activity<input id="roster-search" type="text" value="${esc(state.ui.rosterSearch||'')}"></label><label class="field">Visibility<select id="roster-filter">${['all','active','resting','archived'].map(v=>`<option ${v===filter?'selected':''}>${v}</option>`).join('')}</select></label><button data-action="new-agent">＋ New agent</button></div><div class="roster-grid">${list.map(a=>`<section class="panel roster-card" style="${style(a)}"><div class="roster-heading">${bot(a)}<div><h2>${a.symbol} ${esc(a.name)}</h2><p>${esc(a.role)}</p><span class="pill">${a.practice?'Practice · ':''}${a.lifecycle} · ${esc(status(a.id))}</span></div></div><p>Configuration v${a.version} · ${runs(a.id).length} tasks · ${data.pending(state,a.id).length} queued</p><div class="guide-controls"><button data-manage="edit" data-id="${a.id}">Reassign / edit</button><button data-manage="queue" data-id="${a.id}">Task queue</button><button data-manage="sessions" data-id="${a.id}">Sessions & memory</button><button data-manage="duplicate" data-id="${a.id}">Duplicate configuration</button>${a.lifecycle==='active'?`<button data-manage="rest" data-id="${a.id}">Rest</button>`:`<button data-manage="restore" data-id="${a.id}">Return to Workshop</button>`}${a.lifecycle!=='archived'?`<button data-manage="archive" data-id="${a.id}">Archive</button>`:''}</div><details><summary>Configuration history · ${(state.versions[a.id]||[]).length} saved versions</summary>${(state.versions[a.id]||[]).slice().reverse().map(v=>`<div class="version-record"><strong>Version ${v.version} · ${esc(v.role)}</strong><p>${esc(v.instructions)}</p><p>Document tool: ${v.tool?'enabled':'disabled'} · ${esc(v.format)}</p><details><summary>Inspect saved configuration</summary><pre>${esc(JSON.stringify(v,null,2))}</pre></details><button data-manage="version" data-id="${a.id}" data-version="${v.version}">Restore as new version</button></div>`).join('')}</details></section>`).join('')||'<p>No matching agents.</p>'}</div>`;
  }
  function queueView(){
    const a=agent(),pending=data.pending(state,a.id),history=runs();
    return `<section class="panel form-body"><h2>${a.symbol} ${esc(a.name)}’s assignments</h2><p>Only one task runs at a time for this agent. Pending tasks keep the configuration saved when assigned. Other agents have independent queues.</p><p><strong>${state.queuePaused[a.id]?'Queue held — resume explicitly':'Queue enabled'}</strong> · ${pending.length} pending · ${a.lifecycle}</p><p>Closing or refreshing stops active tasks. Pending tasks survive, but wait for you to resume. No tasks run while this page is closed.</p><div class="guide-controls"><button data-queue="toggle">${state.queuePaused[a.id]?'Resume queue':'Hold queue'}</button>${busy()?`<button data-action="${runtime().active.paused?'resume':'pause'}">${runtime().active.paused?'Resume current task':'Pause current task'}</button><button data-action="cancel">Cancel current task</button>`:''}<button data-view="workshop">Assign another task</button><button data-view="roster">Choose another agent</button></div></section><section class="panel form-body section-space"><h2>Pending assignments</h2>${pending.map((r,i)=>`<article class="queue-item"><h3>${i+1}. ${esc(r.task)}</h3><p>Queued ${time(r.created)} · configuration v${r.config.version}</p><button data-queue="up" data-run="${r.id}" ${i===0?'disabled':''}>Move up</button> <button data-queue="down" data-run="${r.id}" ${i===pending.length-1?'disabled':''}>Move down</button> <button data-queue="cancel" data-run="${r.id}">Cancel pending task</button></article>`).join('')||'<p>No pending assignments.</p>'}</section><section class="panel form-body section-space"><h2>Execution history</h2>${history.filter(r=>r.status!=='queued').map(r=>`<article class="queue-item"><h3>${esc(r.task)}</h3><p>${esc(r.status==='paused'?'waiting · paused':r.status)} · v${r.config.version} · ${time(r.created||r.started)}${r.retryOf?' · retry':''}</p><button data-queue="inspect" data-run="${r.id}">Inspect trace / evaluate</button> ${['failed','cancelled'].includes(r.status)?`<button data-queue="retry" data-run="${r.id}">Retry as new task</button>`:''}</article>`).join('')||'<p>No tasks executed yet.</p>'}</section>`;
  }
  function collaborationPanel(){
    const active=state.agents.filter(a=>a.lifecycle==='active');
    return `<section class="panel collaboration section-space"><div class="panel-head"><div><div class="eyebrow">Recorded collaboration · simulation</div><h2>Research → Evaluation</h2></div><button data-view="queue">Selected agent’s queue</button></div><div class="form-body"><p>The researcher extracts a result from its document. A recorded message delivers that exact output to the evaluator, which runs fixed quality checks. No model reasoning is simulated.</p><form id="workflow-form"><div class="form-pair"><label class="field">Research agent<select name="sender">${active.map(a=>`<option value="${a.id}" ${a.id===(state.ui.sender||state.selected)?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label class="field">Evaluation agent<select name="recipient">${active.map((a,i)=>`<option value="${a.id}" ${a.id===state.ui.recipient||(!state.ui.recipient&&i===1)?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label></div><label class="field">Assignment<input name="task" type="text" maxlength="2000" required value="${esc(state.ui.workflowTask||'Summarize the sample document')}"></label><button class="primary" ${active.length<2?'disabled':''}>Run simulated collaboration →</button> <button type="button" data-flow="demo">Create safe demo pair</button></form><p class="field-help">Choose two different active agents, or create a practice pair. Source text and output become part of the local handoff record and backup.</p>${handoffList()}${handoffInspector()}</div></section>`;
  }
  function handoffList(){return state.handoffs.slice(-8).reverse().map(h=>`<button class="handoff-chip" data-handoff="${h.id}"><span aria-hidden="true">◇ → ◈</span> ${esc(h.senderName)} → ${esc(h.recipientName)} · ${esc(h.status)} · ${time(h.at)}</button>`).join('');}
  function handoffInspector(){
    const h=state.handoffs.find(h=>h.id===state.ui.handoff);if(!h)return '';
    return `<section class="handoff-inspector"><h3>Message inspector · simulated</h3><p>${esc(h.senderName)} sent the completed research output to ${esc(h.recipientName)}. The evaluator checks this exact payload using fixed rules.</p><dl><dt>Message</dt><dd>${h.id}</dd><dt>Workflow</dt><dd>${h.workflowId}</dd><dt>Sent / received</dt><dd>${esc(h.at)} / ${esc(h.receivedAt)}</dd><dt>Sender task → recipient task</dt><dd>${h.senderRunId} → ${h.recipientRunId}</dd><dt>Type / status</dt><dd>${h.type} / ${esc(h.status)}</dd><dt>Retries / error</dt><dd>${h.retries} / ${esc(h.error||'none')}</dd></dl><h4>Actual research output</h4><div class="output">${esc(h.payload.output)}</div><details ${state.settings.advanced?'open':''}><summary>Technical view · actual structured message JSON</summary><pre>${esc(JSON.stringify(h,null,2))}</pre></details></section>`;
  }
  function finishHandoff(r){
    if(r.workflowRecipient&&r.status==='completed'&&!r.sentHandoff){
      const recipient=state.agents.find(a=>a.id===r.workflowRecipient);if(!recipient)return;
      const payload={schema:1,kind:'research.result',simulated:true,sourceTaskId:r.id,assignment:r.task,output:r.events.find(e=>e.type==='task.completed').data.output,sourceDocument:r.config.document,configurationVersion:r.config.version};
      const h={id:uid(),workflowId:r.workflowId,senderId:r.agentId,recipientId:recipient.id,senderName:r.config.name,recipientName:recipient.name,senderRunId:r.id,at:data.now(),receivedAt:data.now(),type:'research.result',payload,status:'delivered',retries:0};
      const target=data.enqueue(state,recipient,'Evaluate research result',{workflowId:r.workflowId,input:structuredClone(payload),handoffId:h.id});h.recipientRunId=target.id;r.sentHandoff=h.id;
      state.handoffs.push(h);state.ui.handoff=h.id;
      data.event(r,'message.sent','Research result sent',{handoffId:h.id,recipientId:recipient.id,payload});
      data.event(target,'message.received','Research result received',{handoffId:h.id,senderId:r.agentId,payload});
      save();pump(recipient.id);
    }
    if(r.handoffId){const h=state.handoffs.find(h=>h.id===r.handoffId);if(h){h.status=r.status==='completed'?'processed':r.status;h.processedAt=data.now();h.error=r.events.findLast(e=>e.data.error)?.data.error||null;}}
  }
  function sharedTimeline(){
    const events=state.runs.flatMap(r=>r.events.map(e=>({...e,config:r.config,workflowId:r.workflowId}))).sort((a,b)=>Date.parse(b.at)-Date.parse(a.at)).slice(0,100);
    return `<section class="panel form-body section-space"><h2>Shared timeline</h2><p>Latest 100 recorded events across all agents: queue changes, tools, results, and handoffs. Select an individual run below for its complete trace and human evaluation.</p><details><summary>Show shared events (${events.length})</summary><div class="shared-events">${events.map(e=>`<article class="shared-event" style="${style(e.config)}"><strong>${e.config.symbol} ${esc(e.config.name)} · ${esc(e.label)}</strong><p>${time(e.at)} · ${esc(e.type)} · v${e.config.version}${e.workflowId?` · workflow ${e.workflowId}`:''}</p>${e.data.handoffId?`<button data-handoff="${e.data.handoffId}">Inspect handoff</button>`:''}<details><summary>Event data</summary><pre>${esc(JSON.stringify(e.data,null,2))}</pre></details></article>`).join('')}</div></details>${handoffList()}${handoffInspector()}</section>`;
  }
  function renderConnections(){
    const world=document.querySelector('.room-world'),h=state.handoffs.at(-1);if(!world||!h)return;
    const from=world.querySelector(`[data-select-agent="${h.senderId}"]`),to=world.querySelector(`[data-select-agent="${h.recipientId}"]`);if(!from||!to)return;
    const x1=Number(from.dataset.wireX)||from.offsetLeft+from.offsetWidth/2,y1=Number(from.dataset.wireY)||from.offsetTop+from.parentElement.offsetTop+60,x2=Number(to.dataset.wireX)||to.offsetLeft+to.offsetWidth/2,y2=Number(to.dataset.wireY)||to.offsetTop+to.parentElement.offsetTop+60;
    const elapsed=Math.max(0,Date.now()-Date.parse(h.at)),path=`M${x1},${y1} Q${(x1+x2)/2},${Math.min(y1,y2)-65} ${x2},${y2}`;
    const overlay=document.createElement('div');overlay.className='message-route';overlay.innerHTML=`<svg width="100%" height="100%" aria-hidden="true"><path d="${path}" fill="none" stroke="var(--route,#61509d)" stroke-width="2" stroke-dasharray="5 5"/>${elapsed<3000?`<circle class="delivery-ring" cx="${x2}" cy="${y2}" r="16"/><circle r="6" fill="var(--route,#61509d)" class="data-packet" style="offset-path:path('${path}');animation-delay:-${elapsed}ms"></circle>`:''}</svg><button data-handoff="${h.id}" style="left:${(x1+x2)/2}px;top:${(y1+y2)/2-40}px" aria-label="Inspect handoff from ${esc(h.senderName)} to ${esc(h.recipientName)}">◇ ${esc(h.status)}</button>`;world.append(overlay);overlay.querySelector('button').onclick=()=>{state.ui.handoff=h.id;save();render();document.querySelector('.handoff-inspector')?.scrollIntoView({behavior:'smooth',block:'center'});};
  }
  function sessionView(){
    const a=agent(),current=state.sessions.find(s=>s.id===a.sessionId),sessions=state.sessions.filter(s=>s.agentId===a.id),memories=state.memories.filter(m=>m.agentId===a.id);
    return `<section class="panel form-body"><h2>${esc(a.name)} · ${esc(current?.title)}</h2><p><strong>Provider:</strong> deterministic simulation. <strong>Token usage / model limit:</strong> not applicable; no model is connected. No exact token counts or context capacity are claimed.</p><p>Identity and configuration survive a fresh session. Chat is grouped by session. Execution history remains in Laboratory. Intentional memory is stored only when you save it.</p><button data-session="fresh">Start fresh session</button> <button data-view="workshop">Open active conversation</button><p class="field-help">Context selected here is attached to task traces for inspection. This extractor still reads its configured document; it does not interpret conversation or retrieve memories automatically.</p></section><div class="view-grid section-space"><section class="panel form-body"><h2>Sessions</h2>${sessions.map(s=>`<article class="queue-item"><h3>${esc(s.title)} ${s.id===a.sessionId?'· active':''}</h3><p>${time(s.created)} · ${state.messages.filter(m=>m.sessionId===s.id).length} messages</p><p>${esc(s.summary||'No summary saved.')}</p><button data-session="open" data-id="${s.id}">Return to conversation</button> <button data-session="reuse" data-id="${s.id}" ${!s.summary?'disabled':''}>Attach summary to active context</button><details><summary>Edit session summary</summary><form data-summary="${s.id}"><label class="field">Your intentional summary<textarea name="summary" maxlength="4000" required>${esc(s.summary)}</textarea></label><button>Save summary</button></form></details></article>`).join('')}<h3>Selected context for next tasks</h3>${(current?.context||[]).map((c,i)=>`<p>${esc(c.text)} <button data-session="remove-context" data-index="${i}">Remove</button></p>`).join('')||'<p>No historical context selected.</p>'}</section><section class="panel form-body"><h2>Intentional memory</h2><p>Saved locally, unencrypted, and included in exports. Do not store passwords, API keys, or sensitive personal details. Nothing is retained here automatically.</p><form id="memory-form"><label class="field">Information worth keeping<textarea name="memory" maxlength="4000" required placeholder="A useful preference or fact…"></textarea></label><button>Save memory</button></form>${memories.map(m=>`<article class="queue-item"><form data-memory="${m.id}"><label class="field">Saved memory<textarea name="text" maxlength="4000" required>${esc(m.text)}</textarea></label><button>Save edit</button> <button type="button" data-session="use-memory" data-id="${m.id}">Attach to context</button> <button type="button" data-session="delete-memory" data-id="${m.id}">Delete memory</button></form></article>`).join('')}</section></div>`;
  }
  function contextLesson(){return `<section class="panel form-body section-space"><div class="eyebrow">Hands-on context lesson</div><h2>A fresh session, the same agent</h2><p>Tokens are pieces of text a model processes. A context window limits how many pieces it can consider at once; it has to leave room for its answer and tool results. When a real model reaches that limit, start fresh and deliberately carry forward a useful summary instead of the entire transcript.</p><p>History is your record of what happened. Context is what a model is given now. Long-term memory is information you intentionally save for later retrieval. This simulator has no model context limit.</p><ol><li>Open Sessions & memory and save a short summary of your current session.</li><li>Start a fresh session. Your agent and execution history remain.</li><li>Attach the old summary to the new session’s context.</li><li>Save one useful memory, then edit or remove it.</li></ol><button data-view="sessions">Try it with ${esc(agent().name)} →</button></section>`;}
  function settingsView(){return `<section class="panel form-body"><h2>Workshop atmosphere</h2><p>Appearance is saved separately from agent configurations. All themes share the same data and controls.</p><label class="field">Theme<select id="theme-select"><option value="neon">Neon Noir</option><option value="spectrum">Spectrum Studio</option><option value="forest">Forest Sanctuary</option></select></label><p>Your device’s reduced-motion preference is respected. Simulation requires no API key and makes no provider requests.</p><h3>Local workspace storage</h3><p>Data lives in this browser, on this site address. It does not sync across devices or between the local preview and GitHub Pages. Export before switching addresses or clearing browser storage; import your backup at the new address. Exports contain chats, source documents, summaries, memories, and execution records.</p><button data-action="export">Export workshop backup</button> <button data-action="import">Import backup</button></section>`;}
  function bindManagement(){
    document.querySelector('[data-scene-console]')?.addEventListener('click',()=>{document.querySelector('.chat')?.scrollIntoView({behavior:'smooth',block:'center'});document.getElementById('task-input')?.focus({preventScroll:true});});
    const themes=document.getElementById('theme-select');if(themes){themes.value=WorkshopTheme.current;themes.onchange=()=>{const saved=WorkshopTheme.select(themes.value);render();if(!saved)toast('Theme applied for this visit; browser storage is unavailable.');};}

    document.getElementById('roster-search')?.addEventListener('input',e=>{state.ui.rosterSearch=e.target.value;save();render();});
    document.getElementById('roster-filter')?.addEventListener('change',e=>{state.ui.rosterFilter=e.target.value;save();render();});
    document.querySelectorAll('[data-manage]').forEach(el=>el.onclick=()=>{
      const a=state.agents.find(a=>a.id===el.dataset.id),action=el.dataset.manage;if(!a)return;
      if(['rest','archive','version'].includes(action)&&busy(a.id)){toast('Finish or cancel this agent’s current task first. Pausing alone keeps its runtime active.');return;}
      if(action==='edit'||action==='queue'||action==='sessions'){state.selected=a.id;selectedRun=null;go(action==='edit'?'blueprint':action);return;}
      if(action==='rest'||action==='archive'){a.lifecycle=action==='rest'?'resting':'archived';state.queuePaused[a.id]=true;}
      if(action==='restore'){a.lifecycle='active';toast('Agent restored. Held assignments stay held until you resume its queue.');}
      if(action==='duplicate'){
        const copy={...structuredClone(a),id:uid(),name:(a.name+' copy').slice(0,32),document:SAMPLE,version:1,lifecycle:'active',practice:false,sessionId:null};
        delete copy.memory;state.agents.push(identity.normalize(copy));ensureSession(copy);state.agents[state.agents.length-1]=copy;state.versions[copy.id]=[structuredClone(copy)];toast('New identity created. Source documents, memories, sessions, and run history were not copied.');
      }
      if(action==='version'){const v=state.versions[a.id].find(v=>v.version===Number(el.dataset.version));if(v){data.version(state,a,v);delete state.drafts.agents[a.id];toast('Earlier settings restored as a new version. Historical runs are unchanged.');}}
      save();render();
    });
    document.querySelectorAll('[data-queue]').forEach(el=>el.onclick=()=>{
      const r=state.runs.find(r=>r.id===el.dataset.run),action=el.dataset.queue;
      if(action==='toggle'){state.queuePaused[agent().id]=!state.queuePaused[agent().id];save();pump(agent().id);}
      if(action==='up'||action==='down')data.reorder(state,r.id,action==='up'?-1:1);
      if(action==='cancel'&&r?.status==='queued'){r.status='cancelled';r.finished=data.now();data.event(r,'task.cancelled','Pending task cancelled');finishHandoff(r);}
      if(action==='retry'){retryRun(r);return;}if(action==='inspect'){selectedRun=r.id;go('laboratory');return;}save();render();
    });
    const workflow=document.getElementById('workflow-form');if(workflow){workflow.onchange=()=>{state.ui.sender=workflow.elements.sender.value;state.ui.recipient=workflow.elements.recipient.value;state.ui.workflowTask=workflow.elements.task.value;save();};workflow.oninput=workflow.onchange;workflow.onsubmit=e=>{
      e.preventDefault();const f=new FormData(workflow),sender=state.agents.find(a=>a.id===f.get('sender')),recipient=state.agents.find(a=>a.id===f.get('recipient')),task=String(f.get('task')).trim();if(!sender||!recipient||sender.id===recipient.id||!task){toast('Choose two different active agents and an assignment.');return;}
      const r=data.enqueue(state,sender,task,{workflowId:uid(),workflowRecipient:recipient.id});save();pump(sender.id);render();toast('Research assignment queued. Its completed output will be delivered to the evaluator.');
    };}
    document.querySelector('[data-flow="demo"]')?.addEventListener('click',()=>{
      const pair=['Research','Evaluation'].map((role,i)=>{const a=makeAgent('Practice '+role,state.agents.length+i);a.role=role;a.practice=true;a.lifecycle='active';state.agents.push(a);ensureSession(a);return a;});state.ui.sender=pair[0].id;state.ui.recipient=pair[1].id;state.selected=pair[0].id;save();render();
    });
    document.querySelectorAll('[data-handoff]').forEach(el=>el.onclick=()=>{state.ui.handoff=el.dataset.handoff;save();render();document.querySelector('.handoff-inspector')?.scrollIntoView({behavior:'smooth',block:'center'});});
    document.querySelectorAll('[data-session]').forEach(el=>el.onclick=()=>{
      const a=agent(),action=el.dataset.session,s=state.sessions.find(s=>s.id===el.dataset.id&&s.agentId===a.id),current=state.sessions.find(s=>s.id===a.sessionId),m=state.memories.find(m=>m.id===el.dataset.id&&m.agentId===a.id);
      if(action==='fresh'){a.sessionId=null;ensureSession(a);state.sessions.find(s=>s.id===a.sessionId).title='Session '+state.sessions.filter(s=>s.agentId===a.id).length;}
      if(action==='open'&&s){a.sessionId=s.id;save();go('workshop');return;}
      if(action==='reuse'&&s?.summary&&!current.context.some(c=>c.sourceId===s.id))current.context.push({sourceId:s.id,text:s.summary,kind:'session-summary'});
      if(action==='use-memory'&&m&&!current.context.some(c=>c.sourceId===m.id))current.context.push({sourceId:m.id,text:m.text,kind:'memory'});
      if(action==='delete-memory'&&m){state.memories=state.memories.filter(x=>x.id!==m.id);for(const s of state.sessions)s.context=s.context.filter(c=>c.sourceId!==m.id);toast('Memory and selected copies removed. Past run snapshots and exported backups remain unchanged.');}
      if(action==='remove-context')current.context.splice(Number(el.dataset.index),1);save();render();
    });
    document.querySelectorAll('[data-summary]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const s=state.sessions.find(s=>s.id===form.dataset.summary);s.summary=String(new FormData(form).get('summary')).trim();save();render();});
    document.querySelectorAll('[data-memory]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const m=state.memories.find(m=>m.id===form.dataset.memory);m.text=String(new FormData(form).get('text')).trim();save();render();});
    document.getElementById('memory-form')?.addEventListener('submit',e=>{e.preventDefault();const text=String(new FormData(e.target).get('memory')).trim();if(!text)return;state.memories.push({id:uid(),agentId:agent().id,text,created:data.now()});save();render();});
  }

  save();render();
})();
